<?php
declare(strict_types=1);
if(!defined('CWP_BOOT')){http_response_code(404);exit;}
require_once CWP_CODE_ROOT.'/app/providers/package_wordpress_installed.php';
function provider_wp_installed_label(string $status):string {return match($status){'observed'=>'Latest saved WordPress installation indication','stale'=>'Saved WordPress installation indication is out of date','unfinished'=>'Latest refresh has no saved result','complete'=>'Saved WordPress installation indication','assignment_changed'=>'The studio needs to confirm this hosting assignment','not_shared'=>'WordPress installation indication sharing is off','not_observed'=>'No WordPress installation indication has been saved','unavailable','refused','credential','access_changed'=>'Latest refresh did not provide a WordPress installation indication',default=>'WordPress installation indication is unavailable'};}
function provider_wp_installed_render(array $view):void {
    echo '<div data-wordpress-installed-observation><p><strong>'.esc(provider_wp_installed_label($view['status'])).'</strong></p><p class="hint">The WordPress installation indication reported for this website at the time shown. A false response does not confirm that WordPress is absent. This saved indication does not check its version, security or whether the site works.</p>';
    foreach($view['rows'] as $r){$label=match($r['value']){true=>'WordPress reported installed',false=>'Provider reported false',default=>'Installation indication unavailable'};echo '<article class="workspace-message"><h3>'.esc($label).'</h3><p>'.esc(gmdate('Y-m-d H:i:s',$r['observed_epoch'])).' UTC · '.($r['current']?'Latest saved observation':'Historical observation').'</p></article>';}
    echo '</div>';
}
function provider_wp_installed_admin_render():void {
    provider_settings_manager();echo '<section class="workspace-card" id="package-wordpress-installed"><h2>Website WordPress installation</h2><p>Refresh the reported WordPress installation indication for an assigned hosting package. Share its saved observation with that client separately.</p>';
    try{
        if(!provider_inventory_ready()){echo '<p>Prepare hosting inventory first.</p></section>';return;}
        if(!provider_wp_installed_ready()){echo '<form method="post">';admin_action('provider_inventory_wp_installed_prepare');admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn gold">Enable WordPress installation observations</button></form></section>';return;}
        $page=max(1,min(10000,(int)($_GET['wp_installed_page']??1)));$links=all('SELECT l.id,l.package_id,c.name AS client_name FROM '.table('provider_package_links').' l JOIN '.table('studio_clients').' c ON c.id=l.client_id ORDER BY l.id LIMIT 20 OFFSET '.(($page-1)*20));if(!$links)echo '<p>Assign a hosting package to a client first.</p>';
        foreach($links as $link){echo '<article class="workspace-card" data-wordpress-installed-owner-package><h3>'.esc($link['client_name']).' · Package '.esc((string)$link['package_id']).'</h3>';
            try{
                $view=staff_locked(fn()=>staff_transaction(fn()=>provider_wp_installed_project($link['id'],false)));provider_wp_installed_render($view);$permission=$view['permission'];$binding=null;
                try{$binding=staff_locked(fn()=>staff_transaction(fn()=>provider_wp_installed_binding($link['id'])));}catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="hint">'.esc($e->getMessage()).'</p>';}
                if($binding){echo '<form method="post" data-wordpress-installed-refresh>';admin_action('provider_inventory_wp_installed_refresh');foreach(['link_id'=>$link['id'],'binding_sha256'=>$binding->sha256] as $name=>$value)echo '<input type="hidden" name="'.$name.'" value="'.esc($value).'">';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn gold">Refresh WordPress installation indication</button><p class="hint">One read for this website. Hosting inventory must be complete and less than 15 minutes old.</p></form>';}
                echo '<p>'.($permission&&$permission['document']['enabled']?'Sharing is approved for the recorded assignment.':'WordPress installation indication sharing is off.').'</p>';
                if($permission||$view['status']==='observed'){echo '<form method="post" data-wordpress-installed-sharing>';admin_action('provider_inventory_wp_installed_share');foreach(['link_id'=>$link['id'],'expected_id'=>$permission['document']['id']??'','event_id'=>bin2hex(random_bytes(16)),'anchor_id'=>$view['latest_id']??''] as $name=>$value)echo '<input type="hidden" name="'.$name.'" value="'.esc($value).'">';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<div class="button-row">';if($view['status']==='observed')echo '<button class="btn gold" name="sharing" value="enable">Share saved WordPress installation indication</button>';if($permission)echo '<button class="btn outline" name="sharing" value="disable">Turn off WordPress installation sharing</button>';echo '</div><p class="hint">Sharing covers this reviewed observation and later reads for the same approved assignment.</p></form>';}
            }catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p>';}echo '</article>';
        }
        echo '<nav class="button-row" aria-label="WordPress installation observation assignments">';if($page>1)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['wp_installed_page'=>$page-1])).'#package-wordpress-installed">Previous assignments</a>';if(count($links)===20&&$page<10000)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['wp_installed_page'=>$page+1])).'#package-wordpress-installed">More assignments</a>';echo '</nav>';
    }catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p>';}echo '</section>';
}
